import { Platform } from 'react-native';

const APOLLO_BASE64 = '';
const APOLLO_ITALIC_BASE64 = '';

export function injectApolloFontSync(): void {
  if (Platform.OS === 'web' && typeof document !== 'undefined') {
    const styleId = 'wildgotcha-apollo-font-embedded';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        @font-face {
          font-family: 'Apollo';
          src: url(data:font/otf;base64,${APOLLO_BASE64}) format('opentype');
          font-weight: 100 900;
          font-style: normal;
          font-display: block;
        }
        @font-face {
          font-family: 'Apollo-Italic';
          src: url(data:font/otf;base64,${APOLLO_ITALIC_BASE64}) format('opentype');
          font-weight: 100 900;
          font-style: italic;
          font-display: block;
        }
      `;
      document.head.appendChild(style);
    }
  }
}

// Automatically invoke on import for web
injectApolloFontSync();
